    /// <summary>
    /// MPJ_2144_FixedAssetMovement
    /// </summary>
    public void processReport()
    {
        
        AssetBook               metAssetBook;
        AssetBalancesPeriodTmp  metAssetBalancesPeriodTmp = this.getAssetBalancesPeriodTmp();
        Query    q = new Query(this.parmQuery());
        QueryRun qr = new QueryRun(q);

        next processReport();

        while (qr.next())
        {
           
            metAssetBook = qr.get(tablenum(AssetBook)) as AssetBook;
            ttsbegin;
            select forupdate firstonly metAssetBalancesPeriodTmp
                where metAssetBalancesPeriodTmp.AssetId == metAssetBook.AssetId
                &&    metAssetBalancesPeriodTmp.BookId ==  metAssetBook.BookId;

            metAssetBalancesPeriodTmp.METServiceLife = metAssetBook.ServiceLife;
            metAssetBalancesPeriodTmp.METCostCenter  = this.getMETCostCenterByDefaultDimension(metAssetBook);
            metAssetBalancesPeriodTmp.METPersonResponsible = this.getMETPersonResponsibleName(metAssetBook.AssetId);
            metAssetBalancesPeriodTmp.update();
            ttscommit;

        }
    }

/// <summary>
/// MPJ_2144_FixedAssetMovement
/// </summary>
/// <param name = "_metAssetBook">
/// get AssetBook table buffer
/// </param>
/// <returns>
/// rwturn costcenter dimension 
/// </returns>
public Name getMETCostCenterByDefaultDimension(AssetBook _metAssetBook)
{
  
    Name                METCostCenter;
    METCostCenter   =   METHelper::getDimensionValue(_metAssetBook.DefaultDimension,METConstants::costCenter);
    return              METCostCenter;
}

    /// <summary>
    /// MPJ_2144_FixedAssetMovement
    /// </summary>
    /// <param name = "_AssetId">
    /// Based on the AssetId find the Name 
    /// </param>
    /// <returns>
    /// return PersonResponsible name 
    /// </returns>
    public Name getMETPersonResponsibleName(AssetId _AssetId)
    {
        Name            METWorkerResponsible;
        AssetTable      metAssetTable;
        HcmWorker       metHcmWorker;
        DirPersonName   metDirPersonName;
        DirPartyTable   metDirPartyTable;

        select firstonly AssetId,WorkerResponsible from metAssetTable
            where metAssetTable.AssetId == _AssetId
            join RecId from metHcmWorker
                where metHcmWorker.RecId == metAssetTable.WorkerResponsible
            join Person from metDirPersonName
                where metDirPersonName.Person == metHcmWorker.Person
            join RecId,Name from metDirPartyTable
                where metDirPartyTable.RecId == metDirPersonName.Person;


        METWorkerResponsible =  metDirPartyTable.Name;

        return METWorkerResponsible;

    }
